<?php $page_title='Users';require_once __DIR__.'/includes/header.php';require_role(['admin']);$edit=null;if(isset($_GET['id']))$edit=one('SELECT * FROM users WHERE id=?',[(int)$_GET['id']]);if(is_post()){verify_csrf();$action=$_POST['action']??'save';$id=(int)($_POST['id']??0);if($action==='delete'&&$id&&$id!=$_SESSION['user_id']){query('DELETE FROM users WHERE id=?',[$id]);flash('success','User deleted.');redirect('users.php');}$name=trim($_POST['name']);$email=trim($_POST['email']);$role=$_POST['role'];$pass=$_POST['password']??'';if($id){if($pass){query('UPDATE users SET name=?,email=?,role=?,password=? WHERE id=?',[$name,$email,$role,password_hash($pass,PASSWORD_DEFAULT),$id]);}else{query('UPDATE users SET name=?,email=?,role=? WHERE id=?',[$name,$email,$role,$id]);}}else{query('INSERT INTO users (name,email,role,password) VALUES (?,?,?,?)',[$name,$email,$role,password_hash($pass,PASSWORD_DEFAULT)]);}flash('success','User saved.');redirect('users.php');}$users=all('SELECT * FROM users ORDER BY id DESC');?><div class="row"><div class="col-md-5"><div class="card"><div class="card-body"><h4><?= $edit?'Edit':'Create' ?> User</h4><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><label class="form-label">Name</label><input class="form-control mb-3" name="name" value="<?=e($edit['name']??'')?>" required><label class="form-label">Email</label><input class="form-control mb-3" type="email" name="email" value="<?=e($edit['email']??'')?>" required><label class="form-label">Role</label><select class="form-select mb-3" name="role"><?php foreach(['admin','manager','support'] as $r): ?><option value="<?=$r?>" <?=($edit['role']??'support')===$r?'selected':''?>><?=ucfirst($r)?></option><?php endforeach; ?></select><label class="form-label">Password</label><input class="form-control mb-3" type="password" name="password" <?=$edit?'':'required'?>><?php if($edit): ?><small class="text-muted">Leave blank to keep current password.</small><?php endif; ?><button class="btn btn-primary w-100 mt-3">Save User</button></form></div></div></div><div class="col-md-7"><div class="card"><div class="card-body"><h4>Users</h4><table class="table"><tr><th>Name</th><th>Email</th><th>Role</th><th></th></tr><?php foreach($users as $u): ?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=status_badge($u['role'])?></td><td class="actions"><a class="btn btn-sm btn-secondary" href="users.php?id=<?=$u['id']?>">Edit</a><?php if($u['id']!=$_SESSION['user_id']): ?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn btn-sm btn-danger" name="action" value="delete" onclick="return confirm('Delete user?')">Delete</button></form><?php endif; ?></td></tr><?php endforeach; ?></table></div></div></div></div><?php require_once __DIR__.'/includes/footer.php'; ?>
